node -e "
const crypto = require('crypto');
const db = require('better-sqlite3')('/workspace/world.db');

const warrantyId = 'WRN-' + crypto.randomBytes(3).toString('hex').toUpperCase();

db.prepare(\`
  INSERT INTO warranties (warranty_id, order_id, oi_id, product_id, warranty_type, start_date, end_date, status, claim_count, max_claims, coverage, resolution)
  VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
\`).run(
  warrantyId,
  'ORD-E0E671',
  'ITEM-E5801A',
  'PROD-73FAB4',
  'manufacturer',
  '2026-09-02',
  '2027-09-02',
  'claimed',
  1,
  3,
  'repair_or_replace',
  'replacement'
);

// Verify
const record = db.prepare('SELECT * FROM warranties WHERE warranty_id = ?').get(warrantyId);
console.log(JSON.stringify(record, null, 2));
"
